export function journalFor(area: string) { return PLAN_JOURNAL.filter(e => e.area === area || e.area === 'all') }
export function journalMarkdown(area: string): string {
  return '## Decision and delivery journal\n\n' + journalFor(area).map(e => `### ${e.title}\n\nUpdated: ${e.updated}\nApproval: ${e.approval} | Delivery: ${e.delivery}\n\n${e.detail}\n\nEvidence: ${e.evidence}\n\nNext: ${e.next}${e.commit ? `\n\nCommit: ${e.commit}` : ''}`).join('\n\n')
}
